cd /opt/weather-tg; grep -i "gemini\|ai:" run.log | tail -12 | cut -c1-220 | base64 -w0; echo; python3 - 2>&1 <<EOF | base64 -w0
import json,urllib.request,urllib.error,weather_tg_ai as ai
k=ai.gemini_key()
for m,th in [("gemini-3.1-pro-preview",{"thinkingLevel":"low"}),("gemini-pro-latest",{"thinkingLevel":"low"}),("gemini-3.1-pro-preview",None),("gemini-3.7-flash",{"thinkingLevel":"low"}),("gemini-4-argon",None)]:
    body={"contents":[{"parts":[{"text":"Верни JSON {\"a\": \"привет\"}"}]}],"generationConfig":{"responseMimeType":"application/json"}}
    if th: body["generationConfig"]["thinkingConfig"]=th
    try:
        r=urllib.request.urlopen(urllib.request.Request("https://generativelanguage.googleapis.com/v1beta/models/%s:generateContent?key=%s"%(m,k),data=json.dumps(body).encode(),headers={"Content-Type":"application/json"}),timeout=60)
        print(m,th,"OK",r.read()[:120])
    except urllib.error.HTTPError as e:
        print(m,th,"HTTP",e.code,e.read()[:200])
    except Exception as e: print(m,th,"ERR",e)
EOF
